import React, { PropsWithChildren } from 'react';

import { useGridPlotSize } from '../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { getFormattedTicks } from '../../core/functions/formatter-by-ticks.js';
import { getHorizontalNumTicks } from '../../core/functions/ticks.js';
import { XYChartAxesTicksContext } from '../context/axes/XYChartAxesTicks.context.js';
import { useVisibleAxes } from '../hooks/useVisibleAxes.js';

export function XYChartAxesTicksProvider({ children }: PropsWithChildren) {
  const { width } = useGridPlotSize();

  const { config, scales } = useVisibleAxes();

  const bottomScale = scales.bottom;
  const bottomConfig = config.bottom;

  const numTicks = getHorizontalNumTicks(width);

  const bottomTicks = getFormattedTicks(
    numTicks,
    bottomScale,
    bottomConfig?.unit,
    undefined,
  );

  return (
    <XYChartAxesTicksContext.Provider value={{ bottomTicks }}>
      {children}
    </XYChartAxesTicksContext.Provider>
  );
}
